// Foundations carousel: an accordion list that auto-advances on a progress timer, with a media panel
// that fades out the current example before fading in the next. Clicking an item stops the auto-advance.
// Port of ProductsFoundationsCarousel.tsx; markup is generated by port-landing.mjs, and each
// foundation's media is pre-rendered into a <template class="products-foundation-media">.

const AUTO_ADVANCE_MS = 5000;
const C = 'products-foundations-carousel-';

export function initFoundations(root) {
  const items = Array.from(root.querySelectorAll(`.${C}item`));
  const imageArea = root.querySelector(`.${C}image-area`);
  if (items.length === 0 || !imageArea) {
    return undefined;
  }

  const wraps = items.map((item) => item.parentElement.querySelector(`.${C}item-body-wrap`));
  const media = Array.from(document.querySelectorAll('.products-foundation-media')).map((t) => t.innerHTML);

  const state = { activeIndex: 0, isPaused: false, displayedIndex: 0, isExiting: false };
  let heights = [];
  let progressKey = 'play-0';

  function measureHeights() {
    heights = wraps.map((wrap) => wrap.querySelector(`.${C}item-body-inner`)?.scrollHeight ?? 0);
    renderList(state.activeIndex);
  }

  function renderList(previousIndex) {
    const { activeIndex, isPaused } = state;
    items.forEach((item, i) => {
      const isActive = i === activeIndex;
      item.classList.toggle(`${C}item-active`, isActive);
      item.setAttribute('aria-selected', String(isActive));
      wraps[i].classList.toggle(`${C}item-body-wrap-open`, isActive);
      wraps[i].style.maxHeight = isActive ? `${heights[i] ?? 0}px` : '0px';
    });

    // Progress bar: (re)mounted whenever its React key would change, which restarts the CSS animation
    const nextKey = isPaused ? 'paused' : `play-${activeIndex}`;
    if (nextKey !== progressKey || previousIndex !== activeIndex) {
      root.querySelectorAll(`.${C}item-progress`).forEach((el) => el.remove());
      const progress = document.createElement('span');
      progress.className = `${C}item-progress` + (isPaused ? ` ${C}item-progress-full` : '');
      progress.setAttribute('aria-hidden', 'true');
      if (!isPaused) {
        progress.style.animationDuration = `${AUTO_ADVANCE_MS}ms`;
      }
      items[activeIndex].appendChild(progress);
      progressKey = nextKey;
    }
  }

  // Remounts the media panel (React keys it by displayedIndex), which replays its fade-in
  function showMedia(index) {
    const next = document.createElement('div');
    next.className = `${C}media-swap`;
    next.innerHTML = media[index] ?? '';
    imageArea.querySelector(`.${C}media-swap`)?.replaceWith(next);
  }

  function setActive(index) {
    const previous = state.activeIndex;
    state.activeIndex = index;
    renderList(previous);
    if (state.activeIndex === state.displayedIndex) {
      return;
    }
    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
      state.displayedIndex = state.activeIndex;
      state.isExiting = false;
      showMedia(state.displayedIndex);
      return;
    }
    state.isExiting = true;
    imageArea.querySelector(`.${C}media-swap`)?.classList.add(`${C}media-swap-exiting`);
  }

  root.addEventListener('click', (e) => {
    const item = e.target.closest(`.${C}item`);
    if (item) {
      const previous = state.activeIndex;
      state.isPaused = true;
      renderList(previous);
      setActive(items.indexOf(item));
    }
  });

  root.addEventListener('animationend', (e) => {
    if (e.target.classList.contains(`${C}item-progress`) && !state.isPaused) {
      setActive((state.activeIndex + 1) % items.length);
    } else if (e.target.classList.contains(`${C}media-swap`) && state.isExiting) {
      // Fires for both fade-in and fade-out; swap only after the fade-out finishes
      state.displayedIndex = state.activeIndex;
      state.isExiting = false;
      showMedia(state.displayedIndex);
    }
  });

  measureHeights();
  window.addEventListener('resize', measureHeights);
  return () => window.removeEventListener('resize', measureHeights);
}
